import { join, resolve } from 'node:path'


/**
 * Private storage lives outside public/, so @fastify/static can never expose
 * an uploaded object without an authorization check in a route handler.
 */

export const UPLOAD_ROOT = resolve(
    process.env.UPLOAD_DIR ?? './var/uploads'
)

export const STAGING_DIR = join(
    UPLOAD_ROOT,
    'staging'
)

export const OBJECTS_DIR = join(
    UPLOAD_ROOT,
    'objects'
)


/**
 * Storage keys are v4 UUIDs generated by randomUUID(). Validating the exact
 * shape before building a filesystem path means a tampered database row can
 * never become path-traversal input.
 */

export const STORAGE_KEY_PATTERN =
    /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
